          location: { type: 'string', description: 'where in the README (line/quote)' },
          problem: { type: 'string', description: 'the concrete inaccuracy' },
          suggested_fix: { type: 'string' },
        },
        required: ['severity', 'location', 'problem', 'suggested_fix'],
      },
    },
  },
  required: ['crate', 'ok', 'issues'],
}

const REPO = '/Users/smaschek/dev/paigasus/paigasus-helikon'

// Published crates + facade. Each README makes API/import/feature/link claims to verify against source.
const CRATES = [
  { name: 'paigasus-helikon-core' },
  { name: 'paigasus-helikon' },
  { name: 'paigasus-helikon-macros' },
  { name: 'paigasus-helikon-providers-openai' },
  { name: 'paigasus-helikon-providers-anthropic' },
