]

phase('Verify crates')

const checklist = (c) => `You are adversarially fact-checking a rewritten crate README against the REAL source. Be a skeptic: assume the README contains errors and try to find them. READ-ONLY task — do NOT run any git command that moves HEAD or branches, do NOT edit any file.

Repo root: ${REPO}
Crate: ${c.name}
README under test: ${REPO}/crates/${c.name}/README.md

Steps:
1. Read the README at the path above.
2. Read the crate's public surface: ${REPO}/crates/${c.name}/src/lib.rs and any modules it re-exports. For cross-crate references (e.g. types from paigasus-helikon-core, or facade re-exports), read the relevant source in ${REPO}/crates/paigasus-helikon-core/src/ or the facade ${REPO}/crates/paigasus-helikon/src/lib.rs as needed.
3. Verify EVERY one of these against the source — report a finding for each mismatch:
   a. Every Rust type / trait / struct / function / method / macro named in the README actually exists and is public (in this crate or the crate the README attributes it to). Examples to check carefully: constructor names and arity (e.g. \`OpenAiModel::chat(..).build()?\`, \`AnthropicModel::messages(..)\`, \`SqliteSession::open(pool, id).await\`, \`Sandbox::open(path)\`, \`ReadTool::<()>::new(sandbox)\`, \`BashTool::<()>::builder(sandbox).build()\`, \`McpServerHandle::stdio(..).tool_prefix(..).connect().await\`, \`TokioRunner.run(&agent, ctx, input, RunConfig::default())\`, \`LlmAgent::builder::<()>()....build()\`, \`RunResultStreaming::new(stream).collect().await\`, \`result.final_output\`).
   b. Import paths (\`use ...\`) resolve to where those items are actually exported.
   c. Any facade feature names and module aliases match the facade's actual cfg-gated \`pub use\` lines (kebab-case feature -> snake-case module).
   d. Factual claims (e.g. "implements core's Model trait", "SSE transports not supported", "reads OPENAI_API_KEY", the BashTool sandbox caveat) match the source / module docs.
   e. NO stale claim remains: the strings "Stub — see SMA-304", "0.0.0", "not yet published", "currently a scaffold" must NOT appear in a published crate's README.
   f. Links: the docs.rs URL path must equal the crate name. Any book deep-link of the form https://smk1085.github.io/paigasus-helikon/<path>.html must correspond to an existing file ${REPO}/docs/book/src/<path>.md (check with ls/find). The license blob URLs point at LICENSE-APACHE / LICENSE-MIT which exist at repo root.
4. Return the structured verdict. Set ok=true ONLY if you found zero issues. For each issue give severity (high = wrong/non-existent API or broken example a user would copy and hit a compile error / dead link; medium = misleading or imprecise; low = nit), the location (quote the offending line), the concrete problem, and a suggested fix. Do not invent issues — if the README is accurate, say so.`

const results = await parallel(
  CRATES.map((c) => () =>
    agent(checklist(c), { label: `verify:${c.name}`, phase: 'Verify crates', schema: FINDING_SCHEMA })
  )
)

phase('Sweep repo')

const sweep = await agent(
  `READ-ONLY repo-wide consistency sweep for the SMA-424 README refresh. Do NOT move git HEAD/branches and do NOT edit files.

Repo root: ${REPO}

Do these checks and report findings:
1. grep across ALL README.md files (root + crates/*/README.md) for residual stale markers: "Stub — see SMA-304", "Thirteen crates", "version = \\"0.0.0\\"", "not yet published", "currently a scaffold", "TODO(post-publish". List every file:line still containing any of them. (Stub crate READMEs are ALLOWED to say "0.0.0" in the phrase "pre-published 0.0.0 name-claim placeholder" — that is intentional and not stale; flag only OTHER occurrences.)
2. Confirm the 4 stub crate READMEs (evals, runtime-axum, runtime-temporal, runtime-agentcore) and the cli README clearly mark their non-published status and do NOT claim to be published.
3. Read ${REPO}/README.md "Workspace at a glance" section: confirm it lists 14 crates (count the bullet coverage), includes paigasus-helikon-sessions-sqlite, and says "Fourteen crates".
4. Confirm ${REPO}/CLAUDE.md "Workflow conventions" now contains a bullet requiring crate README updates before a PR (search for "Keep crate \`README.md\` files current").
5. Verify the facade README feature->module table matches the facade's actual pub use lines in ${REPO}/crates/paigasus-helikon/src/lib.rs.
6. Sanity-check that every book deep-link path referenced across all the READMEs exists as a .md file under ${REPO}/docs/book/src/ (gather the unique paths and ls them).

Report as crate="repo-sweep" with one issue per real problem (severity, location, problem, suggested_fix). ok=true only if everything checks out.`,
  { label: 'sweep', phase: 'Sweep repo', schema: FINDING_SCHEMA }
)

const all = [...results.filter(Boolean), sweep].filter(Boolean)
const withIssues = all.filter((r) => !r.ok || (r.issues && r.issues.length))
return {
  checked: all.map((r) => r.crate),
  clean: all.filter((r) => r.ok && (!r.issues || !r.issues.length)).map((r) => r.crate),
  findings: withIssues,
}

